use vstd::prelude::*;

verus! {
    fn array_to_sequence(arr: &[bool; 10]) -> (res: Vec<bool>)
        requires
            arr.len() == 10, // The input array must have exactly 10 elements
        ensures
            res.len() == 10, // The output vector must have exactly 10 elements
            forall|k: nat| (k < 10) ==> (res[k as usize] == arr[k]), // Each element in the output matches the input
    {
        let mut res: Vec<bool> = Vec::with_capacity(10); // Initialize a vector with capacity 10
        let mut idx: usize = 0; // Index for iterating over the array

        while idx < 10
            invariant
                idx <= 10, // Ensure idx does not exceed the bounds
                res.len() == idx, // The length of res matches the number of elements added
                forall|k: nat| (k < idx) ==> (res[k] == arr[k]), // Ensure the elements added so far match
            decreases 10 - idx, // Decrease measure for termination
        {
            res.push(arr[idx]); // Push the current element from the array to the vector
            idx = idx + 1; // Increment the index
        }

        res // Return the populated vector
    }
}

